(async () => {
  const page = figma.currentPage;
  const fam = 'Hanken Grotesk';
  for (const s of ['Regular','Medium','SemiBold','Bold','Black']) await figma.loadFontAsync({ family: fam, style: s });
  const PS = {}; for (const st of figma.getLocalPaintStyles()) PS[st.name] = st;
  const TS = {}; for (const st of figma.getLocalTextStyles()) TS[st.name] = st;
  const white = { r: 1, g: 1, b: 1 }, black = { r: 0, g: 0, b: 0 };
  const G = n => PS[n].paints.map(p => ({ ...p }));
  const W = { type:'SOLID', color: white };
  const K = { type:'SOLID', color: black };

  async function txt(str, style, paint = 'Fyrre/Black', nm) {
    const t = figma.createText();
    t.fontName = { family: fam, style: 'Regular' };
    t.characters = str || '';
    t.textStyleId = TS[style].id;
    t.name = nm || (str ? str.slice(0, 50) : 'text');
    t.fills = G(paint);
    return t;
  }
  function layout(n, dir, gap, l, t, r, b) {
    n.layoutMode = dir; n.itemSpacing = gap || 0;
    n.paddingLeft = l || 0; n.paddingTop = t || 0; n.paddingRight = r || 0; n.paddingBottom = b || 0;
    n.primaryAxisAlignItems = 'MIN'; n.counterAxisAlignItems = 'MIN';
  }
  function fr(name, w, h, fill) { const f = figma.createFrame(); f.name = name; f.resize(w, h); f.fills = fill || [W]; f.strokes = []; f.cornerRadius = 0; return f; }
  function cp(name, w, h, fill) { const c = figma.createComponent(); c.name = name; c.resize(w, h); c.fills = fill || [W]; c.strokes = []; c.cornerRadius = 0; return c; }
  function inst(name, parent) {
    const src = page.children.find(n => n.type === 'COMPONENT' && n.name === name);
    if (!src) throw new Error('NO COMPONENT ' + name);
    const i = src.createInstance();
    parent.appendChild(i);
    return i;
  }
  function colorAll(i, col) { i.findAll(n => n.type === 'VECTOR').forEach(v => { v.fills = [{ type: 'SOLID', color: col }]; }); }

  // ---------- Button Light (white bg, black text) ----------
  const btnLight = cp('Button Light', 120, 48);
  layout(btnLight, 'HORIZONTAL', 0, 24, 12, 24, 12);
  btnLight.fills = [W]; btnLight.strokes = [K]; btnLight.strokeWeight = 1; btnLight.primaryAxisAlignItems = 'CENTER'; btnLight.counterAxisAlignItems = 'CENTER';
  btnLight.appendChild(await txt('SIGN UP', 'Fyrre/Button', 'Fyrre/Black', 'SIGN UP'));

  // ---------- Text Field on white ----------
  const tf = cp('Text Field White', 320, 48);
  layout(tf, 'HORIZONTAL', 0, 16, 0, 16, 0); tf.primaryAxisAlignItems = 'MIN'; tf.counterAxisAlignItems = 'CENTER';
  tf.fills = [W]; tf.strokes = [K]; tf.strokeWeight = 1;
  tf.appendChild(await txt('Email', 'Fyrre/Body M', 'Fyrre/Gray 500', 'Email'));

  // ---------- Category Tag ----------
  const tag = cp('Category Tag', 84, 30);
  tag.fills = [W]; tag.strokes = [K]; tag.strokeWeight = 1; tag.cornerRadius = 2;
  layout(tag, 'HORIZONTAL', 0, 12, 5, 12, 5); tag.primaryAxisAlignItems = 'CENTER'; tag.counterAxisAlignItems = 'CENTER';
  tag.appendChild(await txt('Art', 'Fyrre/Tag', 'Fyrre/Black', 'Art'));

  // ---------- Section Label ----------
  const sl = cp('Section Label', 300, 24);
  layout(sl, 'HORIZONTAL', 12, 0, 0, 0, 0); sl.primaryAxisAlignItems = 'MIN'; sl.counterAxisAlignItems = 'CENTER'; sl.fills = [];
  const bar = fr('bar', 24, 2, [K]); sl.appendChild(bar);
  sl.appendChild(await txt('MOST POPULAR', 'Fyrre/Tag', 'Fyrre/Black', 'label'));

  // ---------- Meta ----------
  const meta = cp('Meta', 400, 18);
  layout(meta, 'HORIZONTAL', 8, 0, 0, 0, 0); meta.primaryAxisAlignItems = 'MIN'; meta.counterAxisAlignItems = 'CENTER'; meta.fills = [];
  meta.appendChild(await txt('16. March 2022', 'Fyrre/Meta', 'Fyrre/Gray 600', 'date'));

  // ---------- News Ticker ----------
  const ticker = cp('News Ticker', 1680, 46);
  ticker.fills = [K];
  layout(ticker, 'HORIZONTAL', 0, 32, 0, 0, 0); ticker.primaryAxisAlignItems = 'MIN'; ticker.counterAxisAlignItems = 'CENTER'; ticker.clipsContent = true;
  const label = await txt('NEWS TICKER+++', 'Fyrre/Nav', 'Fyrre/White', 'ticker label');
  ticker.appendChild(label);
  const rep = await txt('Lorem ipsum dolor sit amet consectetur +++ adipiscing elit sed do +++ eiusmod tempor incididunt ut labore +++ dolore magna aliqua +++', 'Fyrre/Nav', 'Fyrre/White', 'ticker items');
  ticker.appendChild(rep);

  // ---------- Header ----------
  const header = cp('Header', 1680, 92);
  header.fills = [W]; header.strokes = []; header.strokes = [{ type: 'SOLID', color: G('Fyrre/Gray 200')[0].color }]; header.strokeWeight = 1; header.strokeAlign = 'INSIDE'; header.strokeBottomWeight = 1; header.strokeTopWeight = 0; header.strokeLeftWeight = 0; header.strokeRightWeight = 0;
  layout(header, 'HORIZONTAL', 0, 96, 0, 96, 0); header.primaryAxisAlignItems = 'MIN'; header.counterAxisAlignItems = 'CENTER';
  const wmWrap = fr('wordmark', 320, 92, []); layout(wmWrap, 'HORIZONTAL', 0, 0, 0, 0, 0); wmWrap.counterAxisAlignItems = 'CENTER';
  const wm = await txt('FYRRE MAGAZINE', 'Fyrre/H4', 'Fyrre/Black', 'wordmark'); wm.letterSpacing = { value: 3, unit: 'PIXELS' };
  wmWrap.appendChild(wm); header.appendChild(wmWrap);
  const navWrap = fr('nav', 520, 92, []); layout(navWrap, 'HORIZONTAL', 44, 0, 0, 0, 0); navWrap.counterAxisAlignItems = 'CENTER';
  const mkItem = async (nm, nmo) => {
    const item = fr(nmo, 96, 92, []); layout(item, 'VERTICAL', 0, 0, 34, 0, 0); item.counterAxisAlignItems = 'CENTER';
    item.appendChild(await txt(nm, 'Fyrre/Nav', 'Fyrre/Black', nm));
    const marker = fr('marker', 24, 2, [K]); marker.name = 'current-' + nm; marker.visible = false;
    item.appendChild(marker);
    return item;
  };
  navWrap.appendChild(await mkItem('Magazine', 'nav item Magazine'));
  navWrap.appendChild(await mkItem('Authors', 'nav item Authors'));
  navWrap.appendChild(await mkItem('Podcast', 'nav item Podcast'));
  header.appendChild(navWrap);
  const socWrap = fr('social', 260, 92, []); layout(socWrap, 'HORIZONTAL', 18, 0, 0, 0, 0); socWrap.counterAxisAlignItems = 'CENTER';
  for (const nm of ['Icon_Instagram','Icon_Twitter','Icon_YouTube','Icon_RSS']) { const ic = inst(nm, socWrap); ic.resize(20, 20); }
  header.appendChild(socWrap);

