  const f1 = fr('f1', 332, 48, [W]); layout(f1, 'HORIZONTAL', 0, 0, 0, 0, 0); f1.counterAxisAlignItems = 'CENTER';
  const tfInst = inst('Text Field White', f1); f1.appendChild(tfInst);
  side.appendChild(f1);
  const b1 = inst('Button', side); b1.name = 'SIGN UP button';
  side.appendChild(b1);

  console.log('A1 DONE');
})();

