(async () => {
  const ws = figma.root.children.find(p => p.name === '03 · Workspace');
  await figma.setCurrentPageAsync(ws);
  const names = ['ArticleCard','FrontItem','EpisodeCard','EpisodeRow','AuthorRow','AuthorItem','NewsletterCard','PodcastCover_Ep05','PrintCover','MetaBlock','SidebarNewsletter','Header','Header/Magazine','FooterBand','NewsTicker','TextLink'];
  const out = {};
  const lvl = (n) => {
    if (!n) return null;
    const o = { t: n.type, w: Math.round(n.width), h: Math.round(n.height) };
    if (n.type === 'TEXT') o.chars = (n.characters || '').slice(0, 36);
    if (n.fills && n.fills[0] && n.fills[0].type === 'IMAGE') o.img = 1;
    o.k = (n.children || []).map(c => c.name + (c.type === 'INSTANCE' ? '~' + c.componentProperties && c.mainComponent ? c.mainComponent.name : '' : ''));
    return o;
  };
  for (const nm of names) {
    const c = ws.children.find(n => n.type === 'COMPONENT' && n.name === nm);
    out[nm] = c ? lvl(c) : 'MISSING';
  }
  return 'CH ' + JSON.stringify(out);
})();

