    if (n.type === 'INSTANCE') { try { o.main = n.mainComponent ? n.mainComponent.name : '?'; } catch(e) {} }
    if (n.fills && n.fills[0] && n.fills[0].type === 'IMAGE') o.img = 1;
    if (n.children) o.k = n.children.map(c => walk(c, d + 1));
    return o;
  };
  info.push(walk(inst, 0));
  let hasSwap = false, hasSetComp = false;
  try { hasSwap = typeof inst.swapComponent === 'function'; } catch(e) {}
  try { hasSetComp = ('component' in inst); } catch(e) {}
  const proto = [];
  try { proto = Object.getOwnPropertyNames(Object.getPrototypeOf(inst)); } catch(e) {}
  return 'CARDDEEP ' + JSON.stringify({ info, hasSwap, hasSetComp, proto: proto.filter(k => /swap|component|main|effect|isRemote/i.test(k)) });
