(async () => {
  const ws = figma.root.children.find(p => p.name === '03 · Workspace');
  await figma.setCurrentPageAsync(ws);
  const frames = ws.children.filter(n => n.type === 'FRAME' && /^0[1-7]_/.test(n.name));
  const audit = {};
  for (const f of frames) {
    const types = {};
    f.findAll(n => n.type === 'INSTANCE').forEach(inst => {
      let main = '?';
      try { main = inst.mainComponent ? inst.mainComponent.name : '?'; } catch(e) {}
      if (!/^(Photo_|Avatar_|Icon_|Logo_|Header|FooterBand|NewsTicker)/.test(main)) {
        if (!types[main]) types[main] = { count: 0, bad: 0, samples: [] };
        const t = types[main];
        t.count++;
        let bad = false;
        if (main === 'ArticleCard' || main === 'FrontItem' || main === 'AuthorArticleItem' || main === 'EpisodeCard' || main === 'EpisodeRow' || main === 'AuthorItem' || main === 'AuthorRow') {
          try {
            const date = inst.findOne(n => n.type === 'TEXT' && n.name === '16. March 2022');
            const title = inst.findOne(n => n.type === 'TEXT' && n.name === 'Hope dies last');
            if (date && title) {
              if (!date.characters.startsWith('16.')) bad = true;
              if (title.characters.length > 34 || title.characters.includes('Duration')) bad = true;
            }
            const kids = inst.children.length;
            const isCard = main === 'ArticleCard' || main === 'FrontItem' || main === 'EpisodeCard';
            if (isCard && kids !== 6) bad = true;
          } catch(e) { bad = true; }
        }
        if (bad) { t.bad++; if (t.samples.length < 2) t.samples.push(inst.name); }
      }
    });
    audit[f.name] = types;
  }
  return 'AUDIT ' + JSON.stringify(audit);
})();

